import{c as a,Q as t,j as o,m as r}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{"title":"Privacy Policy","aside":false,"footer":false},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md","lastUpdated":null}'),i={name:"privacy.md"};function n(d,e,l,s,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="privacy-policy-—-nlpm" tabindex="-1">Privacy Policy — NLPM <a class="header-anchor" href="#privacy-policy-—-nlpm" aria-label="Permalink to &quot;Privacy Policy — NLPM&quot;">​</a></h1><p><em>Last updated: 2026-08-13</em></p><p>NLPM analyzes natural-language artifacts inside your repository. Its explicit <code>$nlpm-*</code> workflows are delivered as a Codex plugin; the scoring rubric covers artifacts authored for Claude Code, Codex CLI, and Antigravity. The standalone Python validator (<code>bin/nlpm-check</code>) runs without an agent runtime. This policy describes the data NLPM handles.</p><h2 id="what-nlpm-reads" tabindex="-1">What NLPM reads <a class="header-anchor" href="#what-nlpm-reads" aria-label="Permalink to &quot;What NLPM reads&quot;">​</a></h2><p>The contents of files in your project (skills, agents, commands, rules, hooks, manifests, and related configuration) when you invoke an <code>$nlpm-*</code> workflow. NLPM reads <code>.codex/nlpm.local.md</code> when present. During a one-time migration it may read legacy NLPM configuration or history from <code>.claude/</code>, but never writes there.</p><h2 id="what-nlpm-writes" tabindex="-1">What NLPM writes <a class="header-anchor" href="#what-nlpm-writes" aria-label="Permalink to &quot;What NLPM writes&quot;">​</a></h2><p>NLPM may write <code>.codex/nlpm.local.md</code>, <code>.codex/nlpm-history.json</code>, and <code>.codex/nlpm-reports/</code>. <code>$nlpm-fix</code> edits only the target artifacts selected by the user. These files stay in the project. The standalone validator (<code>bin/nlpm-check</code>) reads and exits without writing.</p><h2 id="what-nlpm-transmits" tabindex="-1">What NLPM transmits <a class="header-anchor" href="#what-nlpm-transmits" aria-label="Permalink to &quot;What NLPM transmits&quot;">​</a></h2><p>NLPM has no backend, telemetry collector, or phone-home service. When Codex orchestrates a workflow, the repository context it needs is processed by OpenAI under the terms and controls of the user&#39;s Codex account. The standalone validator performs its deterministic checks locally and makes no network call.</p><h2 id="third-parties" tabindex="-1">Third parties <a class="header-anchor" href="#third-parties" aria-label="Permalink to &quot;Third parties&quot;">​</a></h2><p>Optional badge fetching from shields.io occurs only if you opt in by embedding the &quot;Validated by NLPM&quot; badge URL in your README. shields.io&#39;s privacy policy applies in that case.</p><h2 id="what-about-the-auditor-pipeline" tabindex="-1">What about the auditor pipeline? <a class="header-anchor" href="#what-about-the-auditor-pipeline" aria-label="Permalink to &quot;What about the auditor pipeline?&quot;">​</a></h2><p>The <code>auditor/</code> directory inside the NLPM source repo runs a separate GitHub Actions pipeline that audits <strong>other</strong> public plugin and skill repositories (today: Claude Code plugins; Codex CLI and Antigravity discovery is planned). That pipeline runs on the maintainer&#39;s GitHub account, not on your machine. Installing NLPM as a plugin does <strong>not</strong> enroll your repository in that pipeline.</p><h2 id="data-deletion" tabindex="-1">Data deletion <a class="header-anchor" href="#data-deletion" aria-label="Permalink to &quot;Data deletion&quot;">​</a></h2><p>There is no centralized NLPM service data to delete. To remove local NLPM state, delete <code>.codex/nlpm-history.json</code>, <code>.codex/nlpm.local.md</code>, and <code>.codex/nlpm-reports/</code> from your projects, then run <code>codex plugin remove nlpm</code>.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>For privacy questions or to report a discrepancy with this policy: <strong><a href="mailto:xiaolaiapple@gmail.com" target="_blank" rel="noreferrer">xiaolaiapple@gmail.com</a></strong>.</p>',17)])])}const m=a(i,[["render",n]]);export{u as __pageData,m as default};
